import csv, hashlib, json, platform, statistics
from pathlib import Path
root=Path('outputs/native-flow/sst-pressure-comparison')
def record(path):
    p=Path(path)
    return {'path':str(p),'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'bytes':p.stat().st_size}
def read(path):return json.loads(Path(path).read_text())
run_order=['ic0-1','aggregation-1','jacobi-1','jacobi-2','aggregation-2','ic0-2','aggregation-full']
runs={}
for name in run_order:
    folder=root/name
    if not (folder/'runtime.json').exists():continue
    entry={'runtime':read(folder/'runtime.json'),'files':[record(p) for p in sorted(folder.iterdir()) if p.is_file()]}
    if (folder/'flow.diagnostics.json').exists():entry['diagnostics']=read(folder/'flow.diagnostics.json')
    if (folder/'audit.json').exists():
        a=read(folder/'audit.json')
        entry['audit']={k:v for k,v in a.items() if k!='plateWallSamples'}
    method=name.rsplit('-',1)[0]
    command=entry['runtime']['command']
    assert entry['runtime']['method']==method==command[command.index('--pressure-preconditioner')+1]
    assert Path(command[1]).resolve()==Path('outputs/native-flow/sst-normal-refinement/midpoint/mesh.cm2d').resolve()
    if 'diagnostics' in entry:
        assert entry['diagnostics']['pressurePreconditioner']==entry['runtime']['method']
    entry['completedFixed100']=name!='aggregation-full' and entry.get('diagnostics',{}).get('iterations')==100 and entry['diagnostics']['stopReason']=='iteration-limit'
    runs[name]=entry
means={}
for method in ['ic0','aggregation','jacobi']:
    selected=[e for n,e in runs.items() if n.startswith(method+'-') and e['completedFixed100']]
    if selected:
        means[method]={'samples':len(selected),'nativeSeconds':statistics.mean(e['diagnostics']['solveSeconds'] for e in selected),
                       'pressureSeconds':statistics.mean(e['diagnostics']['performance']['pressureLinearSeconds'] for e in selected),
                       'pressureIterations':[e['diagnostics']['performance']['pressureIterations'] for e in selected]}

def field_diff(a,b):
    with Path(str(a)+'.cells.csv').open() as f:left=list(csv.DictReader(f))
    with Path(str(b)+'.cells.csv').open() as f:right=list(csv.DictReader(f))
    assert len(left)==len(right)
    result={}
    for key in ['u','v','p','k','omega']:
        pairs=[(float(x[key]),float(y[key])) for x,y in zip(left,right)]
        assert all(x['cell']==y['cell'] for x,y in zip(left,right))
        result[key]={'maxAbsoluteDifference':max(abs(x-y) for x,y in pairs),
                     'maxReferenceMagnitude':max(abs(x) for x,y in pairs)}
    return result
comparison={}
for method in ['aggregation','jacobi']:
    if runs.get(method+'-1',{}).get('completedFixed100'):
        comparison[method]=field_diff(root/'ic0-1/flow.unconverged',root/(method+'-1')/'flow.unconverged')
baseline=Path('outputs/native-flow/sst-normal-refinement/midpoint')
study={'scope':'SST pressure-preconditioner comparison on one 24000-cell wall-resolved flat plate; fixed work is not convergence or physical accuracy',
       'baseCommit':'e608d2c','host':platform.platform(),'defaultPressureUnchanged':'ic0',
       'mesh':record(baseline/'mesh.cm2d'),'binary':record('build/cartmesh2d_sst_rans_probe'),
       'sourceFiles':[record(p) for p in ['tests/sst_rans_probe.cpp','tools/verification/verify_sst_rans.py','tests/sst_rans_verifier_test.py']],
       'runOrder':run_order,'runs':runs,'fixedWorkMeans':means,'fixedWorkFieldDifference':comparison,
       'timingLimitations':'Native solveSeconds used for comparisons; process wall time includes I/O and up to 2s polling delay. Two observations do not establish statistical performance. Sequential local macOS runs only.',
       'monitor':{'file':record(root/'run_one.py'),'source':(root/'run_one.py').read_text()},
       'rawRoot':str(root),'thresholdsChanged':False}
if runs.get('aggregation-full',{}).get('audit',{}).get('valid'):
    old_meta=read(baseline/'flow.json');new_meta=read(root/'aggregation-full/flow.json')
    control_keys=['case','flatPlateLeadingEdge','flatPlateTop','model','scope','nu','speed','inletK','inletOmega','initialK','initialOmega','tolerance','scalarRelativeTolerance','scalarAbsoluteTolerance','scalarCellTolerance','convection','viscousStress','turbulenceUpdatesPerIteration','turbulenceCompletionUpdates','scalarCorrectionsPerUpdate','scalarPreconditioner','cells']
    assert all(old_meta[k]==new_meta[k] for k in control_keys)
    study['matchingFullRunControls']={k:old_meta[k] for k in control_keys}
    study['fullComparison']={'baselineDiagnostics':read(baseline/'flow.diagnostics.json'),
        'baselineFiles':[record(baseline/f) for f in ['flow.json','flow.cells.csv','flow.faces.csv','flow.history.csv','audit.json']],
        'fieldDifference':field_diff(baseline/'flow',root/'aggregation-full/flow'),
        'scope':'One earlier IC0 full solve and one new aggregation full solve; same mesh/physics/initial values/tolerances/core numerical code. Not paired repeated full-run timing.'}
baseline_hashes={}
for line in (baseline/'hashes-pre-run.sha256').read_text().splitlines():
    digest,path=line.split(None,1);baseline_hashes[path]=digest
study['coreLibraries']=[record(p) for p in ['build/libcartmesh2d_fv.a','build/libcartmesh2d.a']]
study['coreLibrariesIdenticalToBaseline']=all(r['sha256']==baseline_hashes[r['path']] for r in study['coreLibraries'])
assert study['coreLibrariesIdenticalToBaseline']
study['baselineHashFile']=record(baseline/'hashes-pre-run.sha256')
study['summarizer']={'file':record(root/'summarize.py'),'source':(root/'summarize.py').read_text()}
study['renderer']=record('tools/visualization/render_sst_pressure_comparison.py')
for name in ['build.log','ctest.log','frontend.log']:
    p=root/name
    if p.exists():study.setdefault('validationLogs',[]).append(record(p))
if (root/'physical-analysis.json').exists():
    a=read(root/'physical-analysis.json');study['physicalAnalysisFile']=record(root/'physical-analysis.json');study['physicalComparisons']=a.get('comparisons')
out=Path('artifacts/current/native-sst-pressure-comparison.json');out.write_text(json.dumps(study,indent=2,allow_nan=False)+'\n')
print(json.dumps({'means':means,'runs':{n:e.get('diagnostics',{}).get('stopReason','no diagnostics') for n,e in runs.items()}},indent=2))
